export const dictionary = Object.fromEntries(Object.entries(rows).map(([key, value]) => [key, value.split('|')]));
export function translate(text, language = 'en') {
  const index = languages.findIndex(item => item.code === language);
  if (index < 1) return text;
  return dictionary[text]?.[index - 1] || text;
}
